def compute_a(n_max):
    a = [0] * (n_max + 1)
    a[1] = 1
    a[2] = 1
    for n in range(3, n_max + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        # We need to ensure indices are within range [1, n-1]
        idx1 = a[n-1]
        idx2 = n - a[n-1]
        # Safety check for indices
        if 1 <= idx1 < n and 1 <= idx2 < n:
            a[n] = a[idx1] + a[idx2]
        else:
            a[n] = None # Mark as undefined if it fails
            break
    return a

