    a[2] = 1
    for n in range(3, n_max + 1):
        idx1 = a[n-1]
        idx2 = n - a[n-1]
        if 1 <= idx1 < n and 1 <= idx2 < n:
            a[n] = a[idx1] + a[idx2]
        else:
            a[n] = None
            break
    return a

